<!-- 世界工具面板：配置导航、流送、场景空间和运行检查。 -->
<template>
  <section class="world-tools" @focusin="form17.focus" @change="form17.change">
    <UiPanelHeader :title="t('worldTools')" :description="t('worldToolsHint')"></UiPanelHeader>
    <UiTabs :aria-label="t('worldTools')" :model-value="activeTab" :items="tabs.map(id => ({id,label:t(`worldTab_${id}`)}))" @update:model-value="activeTab = tabs.find(item => item === $event) ?? activeTab" />
    <p v-if="form17.error.value" class="form-error17" role="alert">{{ form17.error.value }}</p>
    <SimulationStatusPanel17 />
    <div class="workspace">
      <aside>
        <UiButton icon="add" v-if="activeTab !== 'simulation'" class="primary" @click="addSelectedComponent">{{ t(addLabel) }}</UiButton>
        <div v-if="activeTab === 'navigation'" class="quick-adds"><UiButton icon="add" @click="addNavigationObstacle">{{ t('navigationObstacle2D') }}</UiButton><UiButton icon="add" @click="addNavigationAgent">{{ t('navigationAgent2D') }}</UiButton></div>
        <div v-if="activeTab === 'streaming'" class="quick-adds"><UiButton icon="add" @click="addPortal">{{ t('portal2D') }}</UiButton></div>
        <template v-if="activeTab === 'navigation' || activeTab === 'ai'">
          <article class="package-card" :class="{ enabled: activePackageEnabled }">
            <span>{{ activeTab === 'navigation' ? t('navigationPackage') : t('aiPackage') }}</span>
            <strong>{{ activePackageEnabled ? t('packageEnabled') : t('packageNotInstalled') }}</strong>
            <button v-if="!activePackageEnabled" @click="enablePackage">{{ t('enablePackage') }}</button>
          </article>
        </template>
        <UiPropertyRow :label="t('debugOverlay')" v-if="activeTab === 'navigation'"><input v-model="worldGameplayState.navigationDebug" type="checkbox"></UiPropertyRow>
        <template v-if="activeTab === 'navigation'">
          <div class="operation-row"><button class="primary" :disabled="navigationBakeState.active" @click="bakeNavigation">{{ t('bakeNavigation') }}</button><button :disabled="!navigationBakeState.active" @click="cancelNavigationBake">{{ t('cancel') }}</button></div>
          <progress :value="navigationBakeState.progress" max="1"></progress>
          <dl><dt>{{ t('activeAgents') }}</dt><dd>{{ navigationProfile.activeAgents }}</dd><dt>{{ t('deferred') }}</dt><dd>{{ navigationProfile.deferredRepaths }}</dd><dt>{{ t('pathQueries') }}</dt><dd>{{ navigationProfile.pathQueries }}</dd><dt>{{ t('bakedCells') }}</dt><dd>{{ navigationBakeState.cells }}</dd></dl>
        </template>
        <dl v-if="activeTab === 'ai'"><dt>{{ t('activeAgents') }}</dt><dd>{{ aiDebugState.activeAgents }}</dd><dt>{{ t('ticked') }}</dt><dd>{{ aiDebugState.tickedAgents }}</dd><dt>{{ t('deferred') }}</dt><dd>{{ aiDebugState.deferredAgents }}</dd><dt>{{ t('perception') }}</dt><dd>{{ aiDebugState.perceptionQueries }}</dd></dl>
        <template v-if="activeTab === 'simulation'">
          <button class="primary" :disabled="physicsState.selectedEntityIds.length < 3" @click="createRopeLattice">{{ t('createRopeLattice') }}</button>
          <small>{{ t('ropeLatticeHint') }}</small>
          <UiPropertyRow :label="t('physicsDebugger')"><input v-model="physicsDebugState.enabled" type="checkbox"></UiPropertyRow>
          <UiPropertyRow :label="t('navigationDebug')"><input v-model="worldGameplayState.navigationDebug" type="checkbox"></UiPropertyRow>
          <UiPropertyRow :label="t('aiDebug')"><input v-model="worldGameplayState.aiDebug" type="checkbox"></UiPropertyRow>
          <UiPropertyRow :label="t('simulationLabels')"><input v-model="worldGameplayState.simulationDebug" type="checkbox"></UiPropertyRow>
          <UiPropertyRow :label="t('captureReplayEvidence')"><input :checked="simulationEvidenceState.enabled" type="checkbox" @change="toggleEvidence"></UiPropertyRow>
          <button @click="clearSimulationEvidence">{{ t('clearEvidence') }}</button>
          <dl><dt>{{ t('capturedFrames') }}</dt><dd>{{ simulationEvidenceState.frames.length }}</dd><dt>{{ t('stateChecksum') }}</dt><dd>{{ simulationEvidenceState.lastChecksum || '—' }}</dd><dt>{{ t('divergentFrame') }}</dt><dd>{{ simulationEvidenceState.divergentFrame < 0 ? '—' : simulationEvidenceState.divergentFrame }}</dd></dl>
        </template>
        <UiPropertyRow :label="t('debugOverlay')" v-if="activeTab === 'areas'"><input v-model="worldGameplayState.areaDebug" type="checkbox"></UiPropertyRow>
        <UiPropertyRow :label="t('streamingEnabled')" v-if="activeTab === 'streaming'"><input v-model="worldGameplayState.streamingEnabled" type="checkbox"></UiPropertyRow>
        <UiPropertyRow :label="t('memoryBudget')" v-if="activeTab === 'streaming'"><input v-model.lazy.number="worldGameplayState.memoryBudgetMb" type="number" min="1" step="1"></UiPropertyRow>
        <UiPropertyRow :label="t('originShiftThreshold')" v-if="activeTab === 'streaming'"><input v-model.lazy.number="worldGameplayState.originShiftThreshold" type="number" min="1" step="100"></UiPropertyRow>
        <dl v-if="activeTab === 'streaming'"><dt>{{ t('loadedChunks') }}</dt><dd>{{ worldGameplayState.loadedChunks }}</dd><dt>{{ t('memoryUsed') }}</dt><dd>{{ worldGameplayState.usedMemoryMb.toFixed(1) }} MB</dd><dt>{{ t('pendingStreams') }}</dt><dd>{{ worldGameplayState.pendingStreams }}</dd><dt>{{ t('peakMemory') }}</dt><dd>{{ worldStreamingState.peakMemoryMb.toFixed(1) }} MB</dd><dt>{{ t('originShifts') }}</dt><dd>{{ worldGameplayState.originShiftCount }}</dd></dl>
        <button v-if="activeTab === 'streaming' && worldStreamingState.pending" @click="cancelWorldStreaming()">{{ t('cancelStreaming') }}</button>
      </aside>
      <main>
        <section v-if="activeTab === 'simulation'" class="simulation-overview">
          <header><div><h3>{{ t('simulationReadiness') }}</h3><p>{{ t('simulationReadinessHint') }}</p></div><span :class="simulationReport.ready ? 'ready' : 'blocked'">{{ simulationReport.ready ? t('ready') : t('blocked') }}</span></header>
          <div class="simulation-metrics"><article><strong>{{ simulationReport.metrics.bodies }}</strong><span>{{ t('runtimeBodies') }}</span></article><article><strong>{{ simulationReport.metrics.colliderChildren }}</strong><span>{{ t('exactColliderChildren') }}</span></article><article><strong>{{ simulationReport.metrics.ropePaths }}</strong><span>{{ t('ropePaths') }}</span></article><article><strong>{{ simulationReport.metrics.clothNetworks }}</strong><span>{{ t('clothNetworks') }}</span></article><article><strong>{{ simulationReport.metrics.navigationAgents }}</strong><span>{{ t('navigationAgents') }}</span></article><article><strong>{{ simulationReport.metrics.aiAgents }}</strong><span>{{ t('aiAgents') }}</span></article></div>
          <div class="simulation-checks"><article v-for="check in simulationReport.checks" :key="check.id" :class="check.status"><header><strong>{{ t(`simulationCheck_${check.id}`) }}</strong><span>{{ t(`mediaStatus_${check.status}`) }}</span></header><p>{{ localizedSimulationText(check.summaryText, check.summary) }}</p><small>{{ localizedSimulationText(check.detailText, check.detail) }}</small><details data-ui-motion-disclosure v-if="check.status !== 'ready'"><summary>{{ t('howToFix') }}</summary><p>{{ localizedSimulationText(check.fixText, check.fix) }}</p></details></article></div>
          <section v-if="simulationReport.issues.length" class="simulation-issues"><h3>{{ t('simulationIssues') }}</h3><article v-for="issue in simulationReport.issues" :key="`${issue.code}:${issue.message}`"><strong>{{ issue.code }}</strong><p>{{ localizedSimulationText(issue.messageText, issue.message) }}</p><small>{{ localizedSimulationText(issue.fixText, issue.fix) }}</small></article></section>
        </section>

        <div v-else-if="!selectedEntity" class="empty"><strong>{{ t('selectObject') }}</strong><p>{{ t('worldSelectHint') }}</p></div>

        <template v-else-if="activeTab === 'character' && character">
          <h3>{{ selectedEntity.name }} · {{ t('characterBody2D') }}</h3>
          <div class="form-grid"><UiPropertyRow :label="t('maxSlopeAngle')"><input v-model.lazy.number="character.maxSlopeAngle" type="number" min="0" max="89.9" step="1"></UiPropertyRow><UiPropertyRow :label="t('stepHeight')"><input v-model.lazy.number="character.stepHeight" type="number" min="0" step="0.05"></UiPropertyRow><UiPropertyRow :label="t('floorSnap')"><input v-model.lazy.number="character.floorSnap" type="number" min="0" step="0.01"></UiPropertyRow><UiPropertyRow :label="t('coyoteTime')"><input v-model.lazy.number="character.coyoteTime" type="number" min="0" step="0.01"></UiPropertyRow><UiPropertyRow :label="t('safeMargin')"><input v-model.lazy.number="character.safeMargin" type="number" min="0.000000001" step="0.0001"></UiPropertyRow><UiPropertyRow :label="t('maxSlides')"><input v-model.lazy.number="character.maxSlides" type="number" min="1" max="32"></UiPropertyRow><UiPropertyRow :label="t('movingPlatforms')"><input v-model="character.applyPlatformVelocity" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('collisionMask')"><input v-model.lazy.number="character.collisionMask" type="number" min="0" max="4294967295"></UiPropertyRow></div>
          <div class="states"><span :class="{ active: character.onFloor }">{{ t('onFloor') }}</span><span :class="{ active: character.onWall }">{{ t('onWall') }}</span><span :class="{ active: character.onCeiling }">{{ t('onCeiling') }}</span></div>
        </template>

        <template v-else-if="activeTab === 'areas' && area">
          <h3>{{ selectedEntity.name }} · {{ t('area2D') }}</h3>
          <div class="form-grid"><UiPropertyRow :label="t('areaShape')"><select v-model="area.shape" :aria-label="t('shape')"><option>Box</option><option>Circle</option></select></UiPropertyRow><UiPropertyRow :label="t('radius')" v-if="area.shape === 'Circle'"><input v-model.lazy.number="area.radius" type="number" min="0.000001"></UiPropertyRow><UiPropertyRow :label="t('areaSize')" v-else><div><input v-model.lazy.number="area.size.x" type="number" min="0.000001" :aria-label="t('areaSize') + ' X'"><input v-model.lazy.number="area.size.y" type="number" min="0.000001" :aria-label="t('areaSize') + ' Y'"></div></UiPropertyRow></div>
          <section v-if="effector" class="effect-list"><article v-for="effect in effector.effectors" :key="effect.id"><select v-model="effect.kind" :aria-label="t('areaEffector2D')"><option>Gravity</option><option>Wind</option><option>Drag</option><option>Buoyancy</option><option>Damage</option><option>Signal</option></select><UiPropertyRow :label="t('enabled')"><input v-model="effect.enabled" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('direction')" v-if="effect.kind === 'Gravity' || effect.kind === 'Wind'"><div><input v-model.lazy.number="effect.direction.x" type="number" :aria-label="t('direction') + ' X'"><input v-model.lazy.number="effect.direction.y" type="number" :aria-label="t('direction') + ' Y'"></div></UiPropertyRow><UiPropertyRow :label="t('strength')" v-if="effect.kind === 'Gravity' || effect.kind === 'Wind'"><input v-model.lazy.number="effect.strength" type="number"></UiPropertyRow><UiPropertyRow :label="t('drag')" v-if="effect.kind === 'Drag'"><input v-model.lazy.number="effect.drag" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('fluidDensity')" v-if="effect.kind === 'Buoyancy'"><input v-model.lazy.number="effect.fluidDensity" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('damagePerSecond')" v-if="effect.kind === 'Damage'"><input v-model.lazy.number="effect.damagePerSecond" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('signalName')" v-if="effect.kind === 'Signal'"><input v-model="effect.signal"></UiPropertyRow><UiButton icon="clear" class="danger" @click="removeEffector(effect.id)" :label="t('remove')" /></article><UiButton icon="add" @click="addEffector">{{ t('addEffector') }}</UiButton></section>
        </template>

        <template v-else-if="activeTab === 'navigation'">
          <div v-if="region"><h3>{{ selectedEntity.name }} · {{ t('navigationRegion2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('navigationMode')"><select v-model="region.navigationMode"><option>Grid</option><option>Polygon</option></select></UiPropertyRow><UiPropertyRow :label="t('algorithm')"><select v-model="region.algorithm"><option>AStar</option><option>HierarchicalAStar</option><option>FlowField</option></select></UiPropertyRow><UiPropertyRow :label="t('sourceType')"><select v-model="region.source"><option>Manual</option><option>SceneGeometry</option><option>TileMap</option></select></UiPropertyRow><UiPropertyRow :label="t('sourceEntity')" v-if="region.source === 'TileMap'"><select v-model="region.sourceEntityUuid"><option :value="null">{{ t('none') }}</option><option v-for="entity in physicsState.world.entities" :key="entity.uuid" :value="entity.uuid">{{ entity.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('cellSize')"><input v-model.lazy.number="region.cellSize" type="number" min="0.01"></UiPropertyRow><UiPropertyRow :label="t('clusterSize')" v-if="region.algorithm === 'HierarchicalAStar'"><input v-model.lazy.number="region.clusterSize" type="number" min="4" max="64"></UiPropertyRow><UiPropertyRow :label="t('agentRadius')"><input v-model.lazy.number="region.agentRadius" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('traversalCost')"><input v-model.lazy.number="region.traversalCost" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="t('allowDiagonal')"><input v-model="region.allowDiagonal" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('dynamicRebake')"><input v-model="region.dynamic" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('rebakeInterval')"><input v-model.lazy.number="region.rebakeInterval" type="number" min="0.02"></UiPropertyRow><UiPropertyRow :label="t('navigationLayer')"><input v-model.lazy.number="region.navigationLayer" type="number" min="1" max="32"></UiPropertyRow><UiPropertyRow :label="t('navigationMask')"><input v-model.lazy.number="region.navigationMask" type="number" min="0" max="4294967295"></UiPropertyRow></div><UiPropertyRow :label="t('navigationPolygon')" class="stacked"><textarea :value="polygonText" @change="setPolygon"></textarea></UiPropertyRow>
            <section class="production-list"><header><strong>{{ t('navigationLinks') }}</strong><UiButton icon="add" @click="addNavigationLink">{{ t('add') }}</UiButton></header><article v-for="link in region.links" :key="link.id" class="link-row"><input v-model="link.enabled" type="checkbox"><div class="point-editor"><UiPropertyRow :label="t('linkStart')"><input v-model.lazy.number="link.start.x" aria-label="Start X" type="number"><input v-model.lazy.number="link.start.y" aria-label="Start Y" type="number"></UiPropertyRow><UiPropertyRow :label="t('linkEnd')"><input v-model.lazy.number="link.end.x" aria-label="End X" type="number"><input v-model.lazy.number="link.end.y" aria-label="End Y" type="number"></UiPropertyRow></div><UiPropertyRow :label="(t('cost'))"> <input v-model.lazy.number="link.cost" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="(t('bidirectional'))"> <input v-model="link.bidirectional" type="checkbox"></UiPropertyRow><UiButton icon="clear" class="danger" @click="removeNavigationLink(link.id)" :label="t('remove')" /></article></section>
            <section class="production-list"><header><strong>{{ t('costAreas') }}</strong><UiButton icon="add" @click="addNavigationCost">{{ t('add') }}</UiButton></header><article v-for="area in region.costAreas" :key="area.id" class="cost-row"><input v-model="area.enabled" type="checkbox"><input v-model="area.name" :aria-label="t('name')"><select v-model="area.shape" :aria-label="t('shape')"><option>Box</option><option>Circle</option></select><UiPropertyRow :label="t('areaCenter')" class="coordinate-field"><input v-model.lazy.number="area.center.x" aria-label="Center X" type="number"><input v-model.lazy.number="area.center.y" aria-label="Center Y" type="number"></UiPropertyRow><UiPropertyRow :label="t('areaSize')" v-if="area.shape === 'Box'" class="coordinate-field"><input v-model.lazy.number="area.size.x" aria-label="Size X" type="number" min="0.001"><input v-model.lazy.number="area.size.y" aria-label="Size Y" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="(t('radius'))" v-else> <input v-model.lazy.number="area.radius" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="(t('multiplier'))"> <input v-model.lazy.number="area.multiplier" type="number" min="0.001" max="1000"></UiPropertyRow><UiPropertyRow :label="(t('navigationLayer'))"> <input v-model.lazy.number="area.navigationLayer" type="number" min="1" max="32"></UiPropertyRow><UiButton icon="clear" class="danger" @click="removeNavigationCost(area.id)" :label="t('remove')" /></article></section>
          </div>
<!-- 导航目标候选过滤回调排除当前选中实体。 -->          <div v-else-if="agent"><h3>{{ selectedEntity.name }} · {{ t('navigationAgent2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('targetEntity')"><select v-model="agent.targetEntityUuid"><option :value="null">{{ t('none') }}</option><option v-for="entity in physicsState.world.entities.filter(value => value !== selectedEntity)" :key="entity.uuid" :value="entity.uuid">{{ entity.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('targetPosition')"><div><input v-model.lazy.number="agent.targetPosition.x" type="number" :aria-label="t('targetPosition') + ' X'"><input v-model.lazy.number="agent.targetPosition.y" type="number" :aria-label="t('targetPosition') + ' Y'"></div></UiPropertyRow><UiPropertyRow :label="t('speed')"><input v-model.lazy.number="agent.speed" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('acceleration')"><input v-model.lazy.number="agent.acceleration" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('agentRadius')"><input v-model.lazy.number="agent.radius" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="t('stoppingDistance')"><input v-model.lazy.number="agent.stoppingDistance" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('avoidance')"><input v-model="agent.avoidance" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('avoidanceRadius')"><input v-model.lazy.number="agent.avoidanceRadius" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('avoidancePriority')"><input v-model.lazy.number="agent.avoidancePriority" type="number" min="0" max="1" step="0.05"></UiPropertyRow><UiPropertyRow :label="t('avoidanceNeighbors')"><input v-model.lazy.number="agent.maximumAvoidanceNeighbors" type="number" min="1" max="32"></UiPropertyRow><UiPropertyRow :label="t('pathSmoothing')"><input v-model="agent.pathSmoothing" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('repathInterval')"><input v-model.lazy.number="agent.repathInterval" type="number" min="0.02"></UiPropertyRow><UiPropertyRow :label="t('navigationLayer')"><input v-model.lazy.number="agent.navigationLayer" type="number" min="1" max="32"></UiPropertyRow><UiPropertyRow :label="t('navigationMask')"><input v-model.lazy.number="agent.navigationMask" type="number" min="0" max="4294967295"></UiPropertyRow></div><p class="runtime-state">{{ t('pathStatus') }}: {{ agent.pathStatus }} · {{ agent.path.length }} {{ t('waypoints') }}</p></div>
          <div v-else-if="obstacle"><h3>{{ selectedEntity.name }} · {{ t('navigationObstacle2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('areaShape')"><select v-model="obstacle.shape"><option>Circle</option><option>Box</option></select></UiPropertyRow><UiPropertyRow :label="t('radius')" v-if="obstacle.shape === 'Circle'"><input v-model.lazy.number="obstacle.radius" type="number" min="0.001"></UiPropertyRow><UiPropertyRow :label="t('areaSize')" v-else><div><input v-model.lazy.number="obstacle.size.x" type="number" min="0.001" :aria-label="t('areaSize') + ' X'"><input v-model.lazy.number="obstacle.size.y" type="number" min="0.001" :aria-label="t('areaSize') + ' Y'"></div></UiPropertyRow><UiPropertyRow :label="t('dynamicRebake')"><input v-model="obstacle.dynamic" type="checkbox"></UiPropertyRow><UiPropertyRow :label="t('navigationLayer')"><input v-model.lazy.number="obstacle.navigationLayer" type="number" min="1" max="32"></UiPropertyRow><UiPropertyRow :label="t('obstacleVelocity')"><div><input v-model.lazy.number="obstacle.avoidanceVelocity.x" type="number" :aria-label="t('obstacleVelocity') + ' X'"><input v-model.lazy.number="obstacle.avoidanceVelocity.y" type="number" :aria-label="t('obstacleVelocity') + ' Y'"></div></UiPropertyRow></div></div>
        </template>

        <template v-else-if="activeTab === 'ai'">
          <div class="asset-actions"><UiButton icon="add" @click="createBehaviorTree">{{ t('behaviorTree') }}</UiButton><UiButton icon="add" @click="createStateMachine">{{ t('hierarchicalStateMachine') }}</UiButton></div>
          <div v-if="behavior"><h3>{{ t('behaviorTree2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('behaviorAsset')"><select v-model="behavior.treeAsset"><option :value="null">{{ t('none') }}</option><option v-for="asset in behaviorAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('tickRate')"><input v-model.lazy.number="behavior.tickRate" type="number" min="1" max="1000"></UiPropertyRow></div><UiPropertyRow :label="t('blackboardOverrides')" class="stacked"><textarea :value="blackboardOverrideText" @change="setBlackboardOverrides"></textarea></UiPropertyRow><p class="runtime-state">{{ t('activeNode') }}: {{ behavior.currentNode || '—' }}</p><section v-if="selectedAiDebug" class="debug-card"><header><strong>{{ t('visualDebug') }}</strong><span>{{ selectedAiDebug.result ? t('success') : t('failed') }}</span></header><p>{{ t('perceived') }}: {{ selectedAiDebug.perceived }}</p><dl><template v-for="(value,key) in selectedAiDebug.blackboard" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl><p v-if="Object.keys(selectedAiDebug.utility).length">{{ t('utilityScores') }}: {{ JSON.stringify(selectedAiDebug.utility) }}</p></section></div>
          <div v-if="machine"><h3>{{ t('stateMachine2D') }}</h3><UiPropertyRow :label="t('stateMachineAsset')" class="stacked"><select v-model="machine.machineAsset"><option :value="null">{{ t('none') }}</option><option v-for="asset in stateAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow></div>
        </template>

        <template v-else-if="activeTab === 'streaming' && chunk">
          <h3>{{ selectedEntity.name }} · {{ t('worldChunk2D') }}</h3>
          <div class="form-grid">
            <UiPropertyRow :label="t('chunkWorldSize')"><div><input v-model.lazy.number="chunk.size.x" type="number" min="1" :aria-label="t('chunkWorldSize') + ' X'"><input v-model.lazy.number="chunk.size.y" type="number" min="1" :aria-label="t('chunkWorldSize') + ' Y'"></div></UiPropertyRow>
            <UiPropertyRow :label="t('loadDistance')"><input v-model.lazy.number="chunk.loadDistance" type="number" min="0"></UiPropertyRow>
            <UiPropertyRow :label="t('unloadDistance')"><input v-model.lazy.number="chunk.unloadDistance" type="number" min="0"></UiPropertyRow>
            <UiPropertyRow :label="t('prefetchDistance')"><input v-model.lazy.number="chunk.prefetchDistance" type="number" min="0"></UiPropertyRow>
            <UiPropertyRow :label="t('preloadPriority')"><input v-model.lazy.number="chunk.preloadPriority" type="number"></UiPropertyRow>
            <UiPropertyRow :label="t('memoryEstimate')"><input v-model.lazy.number="chunk.memoryEstimateMb" type="number" min="0.001"></UiPropertyRow>
            <UiPropertyRow :label="t('cachePolicy')"><select v-model="chunk.cachePolicy"><option>Release</option><option>Retain</option><option>LRU</option></select></UiPropertyRow>
            <UiPropertyRow :label="t('ownership')"><input v-model="chunk.ownership"></UiPropertyRow>
            <UiPropertyRow :label="t('initiallyLoaded')"><input v-model="chunk.initiallyLoaded" type="checkbox"></UiPropertyRow>
            <UiPropertyRow :label="t('saveStateKey')"><input v-model="chunk.saveStateKey"></UiPropertyRow>
            <UiPropertyRow :label="t('streamScene')"><select v-model="chunk.sceneUuid"><option value="">{{ t('none') }}</option><option v-for="scene in sceneManager.scenes" :key="scene.uuid" :value="scene.uuid">{{ scene.name }}</option></select></UiPropertyRow>
            <UiPropertyRow :label="t('dependencies')"><input :value="dependencyText" @change="setDependencies"></UiPropertyRow>
          </div>
          <section class="stream-cells"><article v-for="cell in worldStreamingState.cells" :key="cell.entityUuid" :class="cell.status.toLowerCase()"><strong>{{ cell.entityUuid.slice(0,8) }}</strong><span>{{ cell.status }}</span><small>{{ cell.memoryMb.toFixed(1) }} MB · {{ cell.dependencies.length }} {{ t('dependencies') }}</small></article></section>
        </template>

        <template v-else-if="activeTab === 'streaming' && portal">
          <h3>{{ selectedEntity.name }} · {{ t('portal2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('targetScene')"><select v-model="portal.targetSceneUuid"><option value="">{{ t('none') }}</option><option v-for="scene in sceneManager.scenes" :key="scene.uuid" :value="scene.uuid">{{ scene.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('targetPortal')"><input v-model="portal.targetPortal"></UiPropertyRow><UiPropertyRow :label="t('triggerRadius')"><input v-model.lazy.number="portal.triggerRadius" type="number" min="0.01"></UiPropertyRow><UiPropertyRow :label="t('preload')"><input v-model="portal.preload" type="checkbox"></UiPropertyRow></div>
        </template>

        <template v-else-if="activeTab === 'pooling' && pool">
          <h3>{{ selectedEntity.name }} · {{ t('objectPool2D') }}</h3><div class="form-grid"><UiPropertyRow :label="t('prefabInstance')"><select v-model="pool.prefabAsset"><option :value="null">{{ t('none') }}</option><option v-for="asset in prefabAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('prewarm')"><input v-model.lazy.number="pool.prewarm" type="number" min="0"></UiPropertyRow><UiPropertyRow :label="t('capacity')"><input v-model.lazy.number="pool.capacity" type="number" min="1"></UiPropertyRow><UiPropertyRow :label="t('autoExpand')"><input v-model="pool.autoExpand" type="checkbox"></UiPropertyRow></div><p class="runtime-state">{{ t('activeInstances') }}: {{ pool.activeCount }}</p>
        </template>

        <div v-else class="empty"><strong>{{ t('componentRequired') }}</strong><p>{{ t('worldAddHint') }}</p></div>
      </main>
    </div>
  </section>
</template>

<script setup lang="ts">
import SimulationStatusPanel17 from './SimulationStatusPanel17.vue'
import { useSimulationFormGuard17 } from '../editor/simulationForm17'

import { computed, ref } from 'vue'
import { assetReference, assetState, createTextAsset } from '../assets/AssetDatabase'
import { t } from '../i18n'
import { addConnection, physicsState, pushHistory, sceneManager } from '../store/physics'
import { Area2D, AreaEffector2D, BehaviorTree2D, CharacterBody2D, NavigationAgent2D, NavigationObstacle2D, NavigationRegion2D, ObjectPool2D, Portal2D, StateMachine2D, WorldChunk2D, type AreaEffectKind2D, type Component2D } from '../world/components'
import { OFFICIAL_AI_PACKAGE_ID, OFFICIAL_NAVIGATION_PACKAGE_ID, enableOfficialPackage, packageEnabled } from '../runtime/packages'
import { worldGameplayState } from '../runtime/worldGameplay'
import { cancelNavigationBake, navigationBakeState, navigationProfile, requestNavigationBake } from '../runtime/navigation2d'
import { aiDebugState } from '../runtime/aiTools'
import { cancelWorldStreaming, worldStreamingState } from '../runtime/worldStreaming'
import { physicsDebugState } from '../runtime/physicsDebug'
import { buildSimulationProductionReport, clearSimulationEvidence, simulationEvidenceState, type SimulationLocalizedText } from '../runtime/simulationAuthoring26'
import { initializeRopeNodes } from '../world/Connection'
import { worldTransform } from '../world/hierarchy'

const form17 = useSimulationFormGuard17(/* 调用 pushHistory('Edit world gameplay settings') 并返回调用结果。 */ () => pushHistory('Edit world gameplay settings'))
type Tab = 'character' | 'areas' | 'navigation' | 'ai' | 'streaming' | 'pooling' | 'simulation'
const tabs: Tab[] = ['character', 'areas', 'navigation', 'ai', 'streaming', 'pooling', 'simulation']
const activeTab = ref<Tab>('character')
const selectedEntity = computed(/** 查找当前选中实体，缺失时返回空值。 */ () => physicsState.world.entities.find(/* 比较 entity.id 与 physicsState.selectedEntityId，返回严格相等的判断结果。 */ entity => entity.id === physicsState.selectedEntityId) ?? null)
const character = computed(/* 调用 selectedEntity.value?.getComponent<CharacterBody2D>('CharacterBody2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<CharacterBody2D>('CharacterBody2D'))
const area = computed(/* 调用 selectedEntity.value?.getComponent<Area2D>('Area2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<Area2D>('Area2D'))
const effector = computed(/* 调用 selectedEntity.value?.getComponent<AreaEffector2D>('AreaEffector2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<AreaEffector2D>('AreaEffector2D'))
const region = computed(/* 调用 selectedEntity.value?.getComponent<NavigationRegion2D>('NavigationRegion2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<NavigationRegion2D>('NavigationRegion2D'))
const agent = computed(/* 调用 selectedEntity.value?.getComponent<NavigationAgent2D>('NavigationAgent2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<NavigationAgent2D>('NavigationAgent2D'))
const obstacle = computed(/* 调用 selectedEntity.value?.getComponent<NavigationObstacle2D>('NavigationObstacle2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<NavigationObstacle2D>('NavigationObstacle2D'))
const behavior = computed(/* 调用 selectedEntity.value?.getComponent<BehaviorTree2D>('BehaviorTree2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<BehaviorTree2D>('BehaviorTree2D'))
const machine = computed(/* 调用 selectedEntity.value?.getComponent<StateMachine2D>('StateMachine2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<StateMachine2D>('StateMachine2D'))
const chunk = computed(/* 调用 selectedEntity.value?.getComponent<WorldChunk2D>('WorldChunk2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<WorldChunk2D>('WorldChunk2D'))
const portal = computed(/* 调用 selectedEntity.value?.getComponent<Portal2D>('Portal2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<Portal2D>('Portal2D'))
const pool = computed(/* 调用 selectedEntity.value?.getComponent<ObjectPool2D>('ObjectPool2D') 并返回调用结果。 */ () => selectedEntity.value?.getComponent<ObjectPool2D>('ObjectPool2D'))
const prefabAssets = computed(/** 筛选预制体资源。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'prefab'，返回严格相等的判断结果。 */ asset => asset.assetType === 'prefab'))
const behaviorAssets = computed(/** 筛选行为树资源。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'behaviorTree'，返回严格相等的判断结果。 */ asset => asset.assetType === 'behaviorTree'))
const stateAssets = computed(/** 筛选状态机资源。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'stateMachine'，返回严格相等的判断结果。 */ asset => asset.assetType === 'stateMachine'))
const activePackageEnabled = computed(/* 调用 packageEnabled(activeTab.value === 'navigation' ? OFFICIAL_NAVIGATION_PACKAGE_ID : OFFICIAL_AI_PACKAGE_ID) 并返回调用结果。 */ () => packageEnabled(activeTab.value === 'navigation' ? OFFICIAL_NAVIGATION_PACKAGE_ID : OFFICIAL_AI_PACKAGE_ID))
const addLabel = computed(/** 将当前世界工具标签映射为组件或就绪状态的翻译键。 */ () => ({ character: 'characterBody2D', areas: 'area2D', navigation: 'navigationRegion2D', ai: 'behaviorTree2D', streaming: 'worldChunk2D', pooling: 'objectPool2D', simulation: 'simulationReadiness' } as const)[activeTab.value])
const polygonText = computed(/* 当 region.value?.polygon.map(point => `${point.x},${point.y}`).join(' ') 为 null 或 undefined 时返回 ''，否则保留左侧值。 */ () => region.value?.polygon.map(/** 将点格式化为逗号分隔的二维坐标。 */ point => `${point.x},${point.y}`).join(' ') ?? '')
const dependencyText = computed(/* 当 chunk.value?.dependencies.join(', ') 为 null 或 undefined 时返回 ''，否则保留左侧值。 */ () => chunk.value?.dependencies.join(', ') ?? '')
const blackboardOverrideText = computed(/* 调用 JSON.stringify(behavior.value?.blackboardOverrides ?? {}, null, 2) 并返回调用结果。 */ () => JSON.stringify(behavior.value?.blackboardOverrides ?? {}, null, 2))
const selectedAiDebug = computed(/** 查找选中实体对应的 AI 调试代理。 */ () => aiDebugState.agents.find(/* 比较 value.entityUuid 与 selectedEntity.value?.uuid，返回严格相等的判断结果。 */ value => value.entityUuid === selectedEntity.value?.uuid) ?? null)
const simulationReport = computed(/** 以当前实体、连接及全局设置生成仿真生产检查报告。 */ () => buildSimulationProductionReport(physicsState.world.entities, physicsState.world.connections, physicsState.globalSettings))
/** 优先使用带参数的本地化说明，翻译键未命中时回退原文。 */ function localizedSimulationText(value: SimulationLocalizedText, fallback: string): string {
  const localized = t(value.key as Parameters<typeof t>[0], value.params)
  return localized === value.key ? fallback : localized
}
/** 切换仿真证据采集开关。 */ function toggleEvidence(): void { simulationEvidenceState.enabled = !simulationEvidenceState.enabled }

/** 为选中实体添加组件并记录历史，没有选择时返回空值。 */ function ensure<T extends Component2D>(component: T): T | null { if (!selectedEntity.value) return null; const result = selectedEntity.value.addComponent(component); pushHistory(`Add ${component.kind}`); return result }
/** 按工具标签添加角色、区域、导航、AI、流送或对象池组件，并按需启用支持包及设置刚体或传感器属性。 */ function addSelectedComponent() {
  if (!selectedEntity.value) return
  if (activeTab.value === 'character') { const value = ensure(new CharacterBody2D()); if (value) { selectedEntity.value.rigidBody.bodyType = 'Kinematic'; selectedEntity.value.rigidBody.gravityScale = 0 } }
  else if (activeTab.value === 'areas') { ensure(new Area2D()); ensure(new AreaEffector2D()); const collider = selectedEntity.value.getCollider(); if (collider) collider.sensor = true }
  else if (activeTab.value === 'navigation') { enableOfficialPackage(OFFICIAL_NAVIGATION_PACKAGE_ID); ensure(new NavigationRegion2D()) }
  else if (activeTab.value === 'ai') { enableOfficialPackage(OFFICIAL_AI_PACKAGE_ID); ensure(new BehaviorTree2D()) }
  else if (activeTab.value === 'streaming') ensure(new WorldChunk2D())
  else ensure(new ObjectPool2D())
}
/** 按导航或其他标签启用对应官方包并记录历史。 */ function enablePackage() { enableOfficialPackage(activeTab.value === 'navigation' ? OFFICIAL_NAVIGATION_PACKAGE_ID : OFFICIAL_AI_PACKAGE_ID); pushHistory('Enable official gameplay package') }
/** 启用导航包并添加导航障碍组件。 */ function addNavigationObstacle() { enableOfficialPackage(OFFICIAL_NAVIGATION_PACKAGE_ID); ensure(new NavigationObstacle2D()) }
/** 启用导航包并添加导航代理组件。 */ function addNavigationAgent() { enableOfficialPackage(OFFICIAL_NAVIGATION_PACKAGE_ID); ensure(new NavigationAgent2D()) }
/** 向区域添加默认双向导航链接并记录历史。 */ function addNavigationLink() { if (!region.value) return; region.value.links.push({ id: crypto.randomUUID(), start: { x: -1, y: 0 }, end: { x: 1, y: 0 }, bidirectional: true, cost: 1, enabled: true }); pushHistory('Add navigation link') }
/** 按标识删除导航链接并记录历史。 */ function removeNavigationLink(id: string) { if (!region.value) return; region.value.links = region.value.links.filter(/* 比较 value.id 与 id，返回严格不等的判断结果。 */ value => value.id !== id); pushHistory('Remove navigation link') }
/** 创建使用当前导航层的默认成本区域并记录历史。 */ function addNavigationCost() { if (!region.value) return; region.value.costAreas.push({ id: crypto.randomUUID(), name: `Cost ${region.value.costAreas.length + 1}`, shape: 'Box', center: { x: 0, y: 0 }, size: { x: 2, y: 2 }, radius: 1, multiplier: 2, navigationLayer: region.value.navigationLayer, enabled: true }); pushHistory('Add navigation cost area') }
/** 按标识删除导航成本区域并记录历史。 */ function removeNavigationCost(id: string) { if (!region.value) return; region.value.costAreas = region.value.costAreas.filter(/* 比较 value.id 与 id，返回严格不等的判断结果。 */ value => value.id !== id); pushHistory('Remove navigation cost area') }
/** 异步请求导航烘焙，并把失败写入世界运行状态。 */ function bakeNavigation() { void requestNavigationBake(physicsState.world.entities).catch(/** 把烘焙异常转换为可见错误字符串。 */ error => { worldGameplayState.lastError = String(error) }) }
/** 为选中实体添加传送门组件。 */ function addPortal() { ensure(new Portal2D()) }
/** 添加带默认风力等参数的区域效果并记录历史。 */ function addEffector() { effector.value?.effectors.push({ id: crypto.randomUUID(), kind: 'Wind' as AreaEffectKind2D, enabled: true, direction: { x: 1, y: 0 }, strength: 5, drag: 1, fluidDensity: 1, damagePerSecond: 10, signal: 'area.effect' }); pushHistory('Add area effector') }
/** 按标识移除区域效果并记录历史。 */ function removeEffector(id: string) { if (!effector.value) return; effector.value.effectors = effector.value.effectors.filter(/* 比较 effect.id 与 id，返回严格不等的判断结果。 */ effect => effect.id !== id); pushHistory('Remove area effector') }
/** 解析空白分隔的二维坐标，至少三个有效点才更新多边形，并限制最多四千零九十六点。 */ function setPolygon(event: Event) { if (!region.value) return; const points = (event.target as HTMLTextAreaElement).value.split(/\s+/).flatMap(/** 将单项逗号坐标转换为有限二维点，无效项忽略。 */ value => { const [x, y] = value.split(',').map(Number); return Number.isFinite(x) && Number.isFinite(y) ? [{ x, y }] : [] }); if (points.length >= 3) { region.value.polygon = points.slice(0, 4096); pushHistory('Edit navigation polygon') } }
/** 解析逗号分隔的流送依赖，清理去重并限量后记录历史。 */ function setDependencies(event: Event) { if (!chunk.value) return; chunk.value.dependencies = [...new Set((event.target as HTMLInputElement).value.split(',').map(/* 调用 value.trim() 并返回调用结果。 */ value => value.trim()).filter(Boolean))].slice(0, 128); pushHistory('Edit stream dependencies') }
/** 解析黑板覆盖对象，仅保留有限基础值并限制键和值长度，无效 JSON 保留上一有效配置。 */ function setBlackboardOverrides(event: Event) { if (!behavior.value) return; try { const parsed: unknown = JSON.parse((event.target as HTMLTextAreaElement).value); if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return; behavior.value.blackboardOverrides = Object.fromEntries(Object.entries(parsed as Record<string, unknown>).slice(0, 256).flatMap(/** 过滤不支持或非有限值，限制键长八十及字符串值长二百五十六。 */ ([key, value]) => ['boolean', 'number', 'string'].includes(typeof value) && !(typeof value === 'number' && !Number.isFinite(value)) ? [[key.slice(0, 80), typeof value === 'string' ? value.slice(0, 256) : value as boolean | number]] : [])); pushHistory('Edit behavior blackboard overrides') } catch { /* Invalid JSON leaves the last valid overrides untouched. */ } }
/** 创建具有感知和效用选择器示例的行为树资源，并关联到选中实体组件。 */ function createBehaviorTree() { const asset = createTextAsset('New Behavior Tree', 'behaviorTree', JSON.stringify({ version: 2, root: 'root', blackboard: { aggression: 0.5 }, perception: [{ id: 'sight', tags: ['player'], radius: 12, fieldOfView: 120, maximumResults: 8, blackboardKey: 'target' }], nodes: [{ id: 'root', type: 'UtilitySelector', name: 'Choose behavior', children: ['chase', 'idle'], condition: '', action: '', seconds: 0 }, { id: 'chase', type: 'Action', name: 'Chase target', children: [], condition: '', action: 'ai.chase', seconds: 0, scoreKey: 'target.count', weight: 1, bias: 0 }, { id: 'idle', type: 'Action', name: 'Idle', children: [], condition: '', action: 'ai.idle', seconds: 0, weight: 0, bias: 0.1 }] }, null, 2), 'Assets/AI'); const component = ensure(new BehaviorTree2D()); if (component) component.treeAsset = assetReference(asset.uuid) }
/** 创建含 idle 初始状态的状态机资源，并关联实体状态机组件。 */ function createStateMachine() { const asset = createTextAsset('New State Machine', 'stateMachine', JSON.stringify({ version: 1, initialState: 'idle', states: [{ id: 'idle', parent: '', onEnter: 'state.idle.enter', onExit: 'state.idle.exit' }], transitions: [] }, null, 2), 'Assets/AI'); ensure(new StateMachine2D())!.machineAsset = assetReference(asset.uuid) }
/** 对最多六十四个已选实体按极角排序，创建缺失的周边及间隔绳索连接并初始化绳节点，最后记录历史。 */ function createRopeLattice() {
  const selected = physicsState.world.entities.filter(/* 调用 physicsState.selectedEntityIds.includes(entity.id) 并返回调用结果。 */ entity => physicsState.selectedEntityIds.includes(entity.id)).slice(0, 64)
  if (selected.length < 3) return
  const center = selected.reduce(/** 累加各实体世界位置除以实体数，计算选择中心。 */ (sum, entity) => { const point = worldTransform(entity, physicsState.world.entities).position; return { x: sum.x + point.x / selected.length, y: sum.y + point.y / selected.length } }, { x: 0, y: 0 })
  const ordered = [...selected].sort(/** 按相对中心的极角排序，角度相同时按实体标识排序。 */ (first, second) => { const a = worldTransform(first, physicsState.world.entities).position, b = worldTransform(second, physicsState.world.entities).position; return Math.atan2(a.y - center.y, a.x - center.x) - Math.atan2(b.y - center.y, b.x - center.x) || first.uuid.localeCompare(second.uuid) })
  const existing = new Set(physicsState.world.connections.flatMap(/** 对恰有两个锚点的连接生成排序后的端点键，用于避免重复连接。 */ connection => connection.anchors.length === 2 ? [connection.anchors.map(/* 返回 anchor.entityId 的当前值。 */ anchor => anchor.entityId).sort(/* 计算表达式 a - b 并返回结果，沿用操作数的原有类型规则。 */ (a, b) => a - b).join(':')] : []))
  const pairs: Array<[number, number]> = []
  for (let index = 0; index < ordered.length; index++) { pairs.push([ordered[index].id, ordered[(index + 1) % ordered.length].id]); if (ordered.length >= 4) pairs.push([ordered[index].id, ordered[(index + 2) % ordered.length].id]) }
  let created = 0
  for (const [first, second] of pairs) {
    const key = [first, second].sort(/* 计算表达式 a - b 并返回结果，沿用操作数的原有类型规则。 */ (a, b) => a - b).join(':'); if (first === second || existing.has(key)) continue; existing.add(key)
    const connection = addConnection([first, second], ['center', 'center'])
    Object.assign(connection, { name: `Constraint path ${physicsState.world.connections.length}`, componentType: 'Rope2D', style: 'straight', collisionEnabled: true, stretchable: true, bendable: true, stiffness: 900, damping: 28, maxStretchRatio: 1.18, bendingToleranceMass: 80, stretchingToleranceMass: 120, collisionRadius: .06, linearDensity: .12, segmentCount: 12 })
    initializeRopeNodes(connection, physicsState.world.entities); created++
  }
  if (created) pushHistory('Create cloth-like Rope2D lattice')
}
</script>

