var(--danger)!important}.stacked{display:flex;flex-direction:column;gap:var(--space-1);color:var(--text-muted)}.asset-actions{display:flex;gap:var(--ui-control-gap);margin-bottom:var(--space-2)}.runtime-state{padding:var(--space-2);border:1px solid var(--border-subtle);color:var(--accent);background:var(--surface-2)}.empty{height:100%;display:grid;place-content:center;text-align:center;color:var(--text-muted)}.empty p{max-width:360px}@container(max-width:850px){.world-tools>header{grid-template-columns:1fr;gap:var(--ui-control-gap)}.world-tools>header>div{min-width:0;display:grid;grid-template-columns:auto minmax(0,1fr);align-items:baseline;gap:var(--space-2)}.world-tools>header small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.world-tools nav{display:grid;grid-template-columns:repeat(6,minmax(0,1fr))}}@container(max-width:600px){.workspace{grid-template-columns:180px minmax(0,1fr)}.world-tools>header>div{display:none}.world-tools nav{grid-template-columns:repeat(3,minmax(0,1fr))}.effect-list article{grid-template-columns:1fr 1fr}}
